SELECT json_build_object('standard', row_to_json(s), 'criteria', (SELECT json_agg(row_to_json(c)) FROM criteria c WHERE c."standardId"=s."standardId"), 'compliances', (SELECT json_agg(row_to_json(co)) FROM compliances co JOIN criteria c ON co."criterionId"=c."criterionId" WHERE c."standardId"=s."standardId"), 'evidence', (SELECT json_agg(row_to_json(e)) FROM evidence e JOIN compliances co ON e."complianceId"=co."complianceId" JOIN criteria c ON co."criterionId"=c."criterionId" WHERE c."standardId"=s."standardId"), 'work', (SELECT json_agg(row_to_json(w)) FROM (SELECT co."complianceNumber", count(*) assessments, count(*) FILTER (WHERE a."scoreId" IS NOT NULL OR a."riskRatingId" IS NOT NULL OR coalesce(a."complianceComments",'')<>'') recorded FROM "complianceAssessments" a JOIN compliances co ON a."complianceId"=co."complianceId" JOIN criteria c ON co."criterionId"=c."criterionId" WHERE c."standardId"=s."standardId" GROUP BY co."complianceNumber") w)) FROM standards s WHERE s."standardNumber"='1';
